const D = { scale:1, energy:.6, supercoil:.5, twist:.55, speed:1, density:.55, hue:178, x:.5, y:.5, style:'molecular', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width,height), cx=width*P.x, t=K.t, sty=P.style;
const hsh = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
const M = Math.max(90, Math.min(210, Math.round(110 + P.density*100)));
const top = height*0.07, len = height*0.86;
const Wturns = 1 + Math.round(P.supercoil*6);           // writhe (superhelix turns)
const Hturns = 5 + Math.round(P.twist*16);              // twist (double-helix turns)
const Wamp = (0.10 + 0.05*P.supercoil)*u*P.scale;
const Rh = (0.055 + 0.03*P.energy)*u*P.scale;
const tw = Math.max(2.5, (0.016+0.014*P.energy)*u*P.scale);
const phH = t*(1.0 + P.speed*1.6);
const phW = t*(0.22 + P.speed*0.18) + 0.6*Math.sin(t*0.13);
const bass = Math.min(0.5, A.bass*0.6);

if (sty==='blueprint') background(214,58,17);
else if (sty==='engraving') background(34,10,56);
else background(206,45,8);

const h0 = P.hue, h1 = sty==='molecular' ? (P.hue+150)%360 : (P.hue+22)%360;
function strandCol(k, lit, glow){
  const h = k?h1:h0;
  if (sty==='blueprint') return [k?208:196, 55, 26+42*lit, glow];
  if (sty==='engraving') return [30, 14, k?(16+22*lit):(22+34*lit), glow];
  return [h, 66, 22+50*lit + 10*bass, glow];
}

// build all drawable elements with depth
const els=[];
const sp=[[],[]];
for (let i=0;i<=M;i++){
  const s=i/M, axisAng=s*Wturns*Math.PI*2 + phW;
  const ax=cx + Wamp*Math.cos(axisAng), az=Wamp*Math.sin(axisAng), ay=top+s*len;
  for (let k=0;k<2;k++){
    const hel=s*Hturns*Math.PI*2 + k*Math.PI + phH;
    const sx=ax + Rh*Math.cos(hel), sz=az + Rh*Math.sin(hel);
    sp[k].push({x:sx, y:ay - sz*0.16, z:sz, s});
  }
}
for (let k=0;k<2;k++) for (let i=0;i<M;i++){ const a=sp[k][i], b=sp[k][i+1]; els.push({type:'s', k, a, b, z:(a.z+b.z)*0.5}); }
const rstep = Math.max(2, Math.round(M/ (Hturns*1.5)));
for (let i=0;i<=M;i+=rstep){ const a=sp[0][i], b=sp[1][i]; els.push({type:'r', a, b, z:(a.z+b.z)*0.5}); }
els.sort((m,n)=>m.z-n.z);

strokeCap(ROUND); strokeJoin(ROUND); noFill();
const zN = Wamp+Rh;
for (const e of els){
  const lit = Math.max(0,Math.min(1,(e.z+zN)/(2*zN)));
  if (e.type==='r'){
    if (sty==='wire'){ stroke((P.hue+60)%360,40,40+35*lit,40*(P.alpha/100)); strokeWeight(1); line(e.a.x,e.a.y,e.b.x,e.b.y); continue; }
    stroke((P.hue+90)%360, 40, 20+40*lit, P.alpha*0.8); strokeWeight(tw*0.5);
    line(e.a.x,e.a.y,e.b.x,e.b.y);
    continue;
  }
  if (sty==='wire'){
    const c=strandCol(e.k,lit,70*(P.alpha/100)); blendMode(ADD);
    stroke(c[0],c[1],40+40*lit, c[3]); strokeWeight(1.4+1.2*lit); line(e.a.x,e.a.y,e.b.x,e.b.y); blendMode(BLEND); continue;
  }
  if (sty==='neon'){
    const c=strandCol(e.k,lit,0); blendMode(ADD);
    stroke(c[0],85,26+30*lit,30*(P.alpha/100)); strokeWeight(tw*1.7); line(e.a.x,e.a.y,e.b.x,e.b.y);
    stroke(c[0],40,92,80*(P.alpha/100)); strokeWeight(tw*0.4); line(e.a.x,e.a.y,e.b.x,e.b.y); blendMode(BLEND); continue;
  }
  if (lit>0.7){ drawingContext.shadowBlur=tw*0.8; drawingContext.shadowColor='rgba(0,0,0,0.5)'; }
  const cc=strandCol(e.k, lit*0.4, P.alpha); stroke(cc[0], cc[1]+6, cc[2]*0.5, P.alpha); strokeWeight(tw*1.2); // casing
  line(e.a.x,e.a.y,e.b.x,e.b.y);
  drawingContext.shadowBlur=0;
  const cb=strandCol(e.k, 0.7+0.5*lit, P.alpha); stroke(cb[0], cb[1], Math.min(100,cb[2]+14), P.alpha); strokeWeight(tw*0.55); // core
  line(e.a.x,e.a.y,e.b.x,e.b.y);
}
// Lk = Tw + Wr readout
if (sty!=='neon' && sty!=='wire'){
  noStroke(); textAlign(LEFT,TOP); textSize(Math.max(10,u*0.016));
  fill(sty==='engraving'?30:(P.hue+40)%360, sty==='engraving'?16:30, sty==='engraving'?26:92, 78*(P.alpha/100));
  text('Lk = Tw + Wr   '+(Hturns+Wturns)+' = '+Hturns+' + '+Wturns, u*0.03, u*0.03);
}
drawingContext.shadowBlur=0;
blendMode(BLEND);
